var _markdown = "\n\n# Styling Guide [#styling-guide]\n\n## Base Styling Props [#base-styling-props]\n\n| Prop                  | Type                    | Description                    |\n| --------------------- | ----------------------- | ------------------------------ |\n| `containerStyle`      | `StyleProp<ViewStyle>`  | Main container style           |\n| `inputContainerStyle` | `StyleProp<ViewStyle>`  | Input container style          |\n| `inputStyle`          | `StyleProp<TextStyle>`  | Text input style               |\n| `tagStyle`            | `StyleProp<ViewStyle>`  | Individual tag container style |\n| `tagTextStyle`        | `StyleProp<TextStyle>`  | Tag text style                 |\n| `deleteIconStyles`    | `StyleProp<ImageStyle>` | Delete button style            |\n| `labelStyle`          | `StyleProp<TextStyle>`  | Label text style               |\n\n## Basic Example [#basic-example]\n\n```tsx\n<TagInput\n  containerStyle={{\n    backgroundColor: '#fff',\n    borderRadius: 8,\n    padding: 12,\n    shadowColor: '#000',\n    shadowOffset: { width: 0, height: 2 },\n    shadowOpacity: 0.1,\n    shadowRadius: 4,\n    elevation: 3,\n  }}\n  inputStyle={{\n    fontSize: 16,\n    color: '#333',\n    paddingHorizontal: 12,\n    height: 40,\n  }}\n  tagStyle={{\n    backgroundColor: '#007AFF',\n    borderRadius: 20,\n    paddingHorizontal: 12,\n    paddingVertical: 6,\n    margin: 4,\n  }}\n  tagTextStyle={{\n    color: '#fff',\n    fontSize: 14,\n    fontWeight: '500',\n  }}\n/>\n```\n\n## Theme Integration [#theme-integration]\n\n```tsx\nconst theme = {\n  colors: {\n    primary: '#007AFF',\n    background: '#FFFFFF',\n    text: '#333333',\n    border: '#E0E0E0',\n    error: '#FF3B30',\n  },\n  spacing: {\n    small: 4,\n    medium: 8,\n    large: 12,\n  },\n  typography: {\n    regular: {\n      fontSize: 14,\n      fontWeight: '400',\n    },\n    medium: {\n      fontSize: 14,\n      fontWeight: '500',\n    },\n  },\n};\n\n<TagInput\n  containerStyle={{\n    backgroundColor: theme.colors.background,\n    borderColor: theme.colors.border,\n    borderWidth: 1,\n    borderRadius: theme.spacing.medium,\n    padding: theme.spacing.large,\n  }}\n  tagStyle={{\n    backgroundColor: theme.colors.primary,\n    borderRadius: theme.spacing.large * 2,\n    paddingHorizontal: theme.spacing.large,\n    paddingVertical: theme.spacing.medium,\n    margin: theme.spacing.small,\n  }}\n  tagTextStyle={{\n    ...theme.typography.medium,\n    color: theme.colors.background,\n  }}\n  inputStyle={{\n    ...theme.typography.regular,\n    color: theme.colors.text,\n  }}\n/>\n```\n\n## Custom Layouts [#custom-layouts]\n\n### Vertical Layout [#vertical-layout]\n\n```tsx\n<TagInput\n  containerStyle={{\n    flexDirection: 'column',\n  }}\n  tagsViewStyle={{\n    flexDirection: 'column',\n    alignItems: 'stretch',\n  }}\n  tagStyle={{\n    marginVertical: 4,\n  }}\n/>\n```\n\n### Grid Layout [#grid-layout]\n\n```tsx\n<TagInput\n  containerStyle={{\n    flexWrap: 'wrap',\n    flexDirection: 'row',\n  }}\n  tagStyle={{\n    width: '45%', // Adjust based on your needs\n    margin: '2.5%',\n  }}\n/>\n```\n\n## Responsive Design [#responsive-design]\n\n```tsx\nimport { Dimensions } from 'react-native';\n\nconst { width } = Dimensions.get('window');\nconst isTablet = width >= 768;\n\n<TagInput\n  containerStyle={{\n    width: isTablet ? '50%' : '100%',\n    alignSelf: 'center',\n  }}\n  tagStyle={{\n    width: isTablet ? 150 : '48%',\n  }}\n  inputStyle={{\n    fontSize: isTablet ? 16 : 14,\n  }}\n/>\n```\n\n## Dark Mode Support [#dark-mode-support]\n\n```tsx\nconst isDarkMode = useColorScheme() === 'dark';\n\nconst styles = StyleSheet.create({\n  container: {\n    backgroundColor: isDarkMode ? '#1C1C1E' : '#FFFFFF',\n    borderColor: isDarkMode ? '#2C2C2E' : '#E0E0E0',\n  },\n  input: {\n    color: isDarkMode ? '#FFFFFF' : '#000000',\n  },\n  tag: {\n    backgroundColor: isDarkMode ? '#0A84FF' : '#007AFF',\n  },\n  tagText: {\n    color: '#FFFFFF',\n  },\n});\n\n<TagInput\n  containerStyle={styles.container}\n  inputStyle={styles.input}\n  tagStyle={styles.tag}\n  tagTextStyle={styles.tagText}\n/>\n```\n";
